import{z as A,x as B,o as e,c as s,q as t,j as l,D as E,d as o,s as i,S as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"下一 token 之外的预训练目标","description":"","frontmatter":{"title":"下一 token 之外的预训练目标","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/beyond-ntp.md","filePath":"llm/beyond-ntp.md","lastUpdated":1791413859000}'),p={name:"llm/beyond-ntp.md"};function T(d,a,h,m,P,f){const n=B("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="下一-token-之外的预训练目标" tabindex="-1">下一 token 之外的预训练目标 <a class="header-anchor" href="#下一-token-之外的预训练目标" aria-label="Permalink to &quot;下一 token 之外的预训练目标&quot;">​</a></h1><div class="epigraph"><p>把所有 NLP 任务收成「把一段文本变成另一段文本」，预训练目标就不必绑死在从左到右的下一个词上。</p><footer>—— Raffel et al., Exploring the Limits of Transfer Learning with a Unified Text-to-Text Transformer, JMLR 2020</footer></div><p><a href="/llm/ul2">上一课</a>用混合去噪把预训练统一成「损坏→还原」，R 接近短 span、S 接近 Prefix、X 用长 span 或高腐蚀连接二者。缺口是：混合物仍是噪声协议，还没有把「何时该离开下一 token」说清楚——损失密度、条件方向、与下游接口是否同构，三者通常不能同时最优。本课把 NTP 放在对照位，看掩码、跨度破坏、替换检测各自约束什么。不重写 R/S/X 配比。后课进入语料清洗时，默认已经读完：换目标不等于换似然。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/ul2">UL2</a>已经把损坏收成混合物，但仍以还原 \\(y\\) 为损失。若问要不要离开下一 token，缺口还在信息流：NTP 的梯度只来自已经出现的左侧上下文。右侧信息、文档级主题、以及「某个位置被挖掉之后如何重建」这类完形填空信号，都不会直接进入损失。对要做分类、抽取、跨句对齐的编码器，这是结构性缺陷：训练时永远看不到未来，推理时却常常需要双向。对生成模型，NTP 也有代价——每个 token 只被预测一次，低频模式与难跨度得不到额外监督，模型容易学会局部流畅而不是文档级一致。</p><p>替代目标要回答的是：在不引入人工标注的前提下，能否换一种噪声与还原协议，让同一段文本产生更密或方向不同的学习信号。Raffel 等人把这个问题收成 T5 的统一框架：输入是带噪声的文本，输出是要还原的片段。噪声怎么造，就是目标怎么定义。</p><h3 id="信息流与损失密度" tabindex="-1">信息流与损失密度 <a class="header-anchor" href="#信息流与损失密度" aria-label="Permalink to &quot;信息流与损失密度&quot;">​</a></h3><p>NTP 对长度为 \\(n\\) 的序列给出 \\(n\\) 个条件分布，损失密度高，但每个位置的条件集是真前缀。掩码语言模型一次只还原被挖掉的位置，双向可见，损失更稀。ELECTRA 一类替换检测把每个位置都变成判别问题，密度回到全序列，却把生成改成了真假分类。选择目标，本质是在「条件方向、监督密度、与下游接口是否同构」之间做取舍。<span class="marginnote">「与下游同构」经常被高估。编码器预训练用掩码、微调做分类，接口并不同构，却长期有效；解码器用 NTP 预训练再做对话，接口更近，也不保证数据与对齐阶段不出问题。同构是工程便利，不是充分条件。</span></p><p><span class="marginnote">直觉类比：损失密度像一张卷子的题量——NTP 是每读一个词就做一道题，一篇 500 词的文章有 500 道题；BERT 式掩码只对被挖掉的约 15% 位置出题，同样的文章只有约 75 道。题多不必然学得好：NTP 的每道题都只能看到左半张卷子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把一段文本 \\(x\\) 经噪声函数变成 \\(\\tilde x\\)，再要求模型预测某个目标 \\(y\\)。NTP 是噪声为空、\\(\\tilde x = x_{\\lt t}\\)、\\(y=x_t\\) 的特例。常见非 NTP 协议如下。</p><p>掩码还原：按比例把 token 换成 <code>[MASK]</code>，预测被掩位置的原词。跨度破坏（T5）：连续跨度被哨兵替换，解码器只生成被抹掉的片段，而不是整句重写。前缀语言建模：前缀段双向可见，后缀段因果生成。替换检测：用一个生成器提议替换，判别器判断每个位置是否被改过。混合去噪（UL2 一类）把多种噪声半径与方向打成任务混合物，用一个哨兵告诉模型当前是哪一种。</p> \\[\\mathcal{L} = \\mathbb{E}_{(x, \\tilde x, y)}\\bigl[-\\log p_\\theta(y \\mid \\tilde x)\\bigr] \\]<p>\\(y\\) 可以是被掩 token、被破坏跨度、整段原文，或每个位置上的真/假标签。目标一旦改变，\\(y\\) 的支撑与 \\(\\tilde x\\) 的可见性一起变，优化景观与可并行度也一起变。</p>',14)),(e(),l(r,null,{default:E(()=>[i(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%8E%9F%E5%A7%8B%E6%96%87%E6%9C%AC%20x%22%5D%20--%3E%20N%5B%22%E5%99%AA%E5%A3%B0%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20N%20--%3E%20MLM%5B%22%E6%8E%A9%E7%A0%81%20%2F%20%E8%B7%A8%E5%BA%A6%E7%A0%B4%E5%9D%8F%22%5D%0A%20%20N%20--%3E%20PLM%5B%22%E5%89%8D%E7%BC%80%E6%9D%A1%E4%BB%B6%E7%94%9F%E6%88%90%22%5D%0A%20%20N%20--%3E%20RTD%5B%22%E6%9B%BF%E6%8D%A2%E6%A3%80%E6%B5%8B%22%5D%0A%20%20N%20--%3E%20MIX%5B%22%E6%B7%B7%E5%90%88%E5%8E%BB%E5%99%AA%22%5D%0A%20%20MLM%20--%3E%20L%5B%22%E8%BF%98%E5%8E%9F%E6%88%96%E5%88%A4%E5%88%AB%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20PLM%20--%3E%20L%0A%20%20RTD%20--%3E%20L%0A%20%20MIX%20--%3E%20L%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="t5-跨度破坏在问什么" tabindex="-1">T5 跨度破坏在问什么 <a class="header-anchor" href="#t5-跨度破坏在问什么" aria-label="Permalink to &quot;T5 跨度破坏在问什么&quot;">​</a></h3><p>C4 上的 T5 并不做 BERT 式单 token 掩码。它采样若干连续跨度，用哨兵替换，解码器按顺序吐出各跨度原文。模型必须：在编码器侧用双向上下文定位缺口，在解码器侧按 NTP 把缺口写出来。这比「只预测一个被掩词」更接近生成，又比纯 NTP 多了「先看全句再写局部」的编码阶段。Raffel 等人同时比较了 BERT 风格掩码、前缀 LM 与跨度破坏，跨度破坏在他们的文本生成设定里更划算——不是因为 NTP 失败，而是因为编码器-解码器加上缺口还原，把双向编码和自回归写出接到了同一套参数上。</p><p><span class="marginnote">跨度长度是超参，不是理论常数。太短接近 BERT；太长接近整句重写，计算浪费在已经可见的 token 上。T5 用平均跨度与掩码率来折中，后续 UL2 把「短缺口 / 长缺口 / 因果」显式分成几种噪声，避免只盯一个半径。</span></p><p><span class="marginnote">常见误区：T5 的哨兵 <code>&lt;extra_id_0&gt;</code> 不是特殊标点，而是一个可以被模型预测出来的「洞的编号」。模型吐出这个编号，意思就是「接下来我写的这段，请填回原文里编号为 0 的那个洞」。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>非 NTP 目标改的是计算图里的可见性掩码，以及损失写在哪些位置上。双向掩码让位置 \\(i\\) 的表示可以读 \\(j\\gt i\\)，前提是 \\(j\\) 未被当成要预测的洞，或洞被哨兵占住。前缀 LM 把可见性切成两段：前缀全连接，后缀三角。替换检测不还原词表分布，只输出一个伯努利，梯度来自「像不像真词」，对生成解码没有直接接口，却对判别式下游很顺。</p>',6)),(e(),l(r,null,{default:E(()=>[i(n,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20LR%0A%20%20P%5B%22%E5%90%8C%E4%B8%80%E5%8F%A5%E8%AF%9D%E8%BF%9B%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20Q%7B%22%E8%AE%AD%E7%BB%83%E6%97%B6%E6%AF%8F%E4%B8%AA%E4%BD%8D%E7%BD%AE%E8%83%BD%E7%9C%8B%E8%A7%81%E4%BB%80%E4%B9%88%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%8F%AA%E8%A7%81%E5%B7%A6%E4%BE%A7%E5%89%8D%E7%BC%80%22%7C%20V1%5B%22NTP%EF%BC%9A%E6%8D%9F%E5%A4%B1%E5%86%99%E5%9C%A8%E4%B8%8B%E4%B8%80%E8%AF%8D%22%5D%0A%20%20Q%20--%3E%7C%22%E5%85%A8%E5%8F%A5%E5%8F%AF%E8%A7%81%EF%BC%8C%E6%B4%9E%E8%A2%AB%E5%8D%A0%E4%BD%8F%22%7C%20V2%5B%22%E6%8E%A9%E7%A0%81%20%2F%20%E8%B7%A8%E5%BA%A6%E7%A0%B4%E5%9D%8F%EF%BC%9A%E6%8D%9F%E5%A4%B1%E5%8F%AA%E5%86%99%E6%B4%9E%E4%B8%8A%22%5D%0A%20%20Q%20--%3E%7C%22%E5%89%8D%E7%BC%80%E5%85%A8%E8%A7%81%EF%BC%8C%E5%90%8E%E7%BC%80%E5%9B%A0%E6%9E%9C%22%7C%20V3%5B%22%E5%89%8D%E7%BC%80%20LM%EF%BC%9A%E6%8D%9F%E5%A4%B1%E5%86%99%E5%90%8E%E7%BC%80%22%5D%0A%20%20Q%20--%3E%7C%22%E5%85%A8%E5%8F%A5%E5%8F%AF%E8%A7%81%22%7C%20V4%5B%22%E6%9B%BF%E6%8D%A2%E6%A3%80%E6%B5%8B%EF%BC%9A%E6%AF%8F%E4%B8%AA%E4%BD%8D%E7%BD%AE%E5%88%A4%E7%9C%9F%2F%E5%81%87%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>这张图回答的问题是：各协议的差别其实只有两处——可见性掩码怎么画、损失写在哪些位置上；其余都是这两处的工程后果。</p><h3 id="监督密度与假阴性" tabindex="-1">监督密度与假阴性 <a class="header-anchor" href="#监督密度与假阴性" aria-label="Permalink to &quot;监督密度与假阴性&quot;">​</a></h3><p>掩码率 15% 意味着 85% 的 token 没有直接损失。提高掩码率能加密监督，但上下文被破坏得太狠，条件分布与真实语言渐行渐远。替换检测把每个位置都变成标签，密度高，可是生成器若太弱，替换一眼假，判别器学不到难例；生成器若太强，替换接近真分布，判别信号又变稀。这是对抗式目标在预训练里的老问题：密度与难度不能靠单一超参同时拉满。</p><p>NTP 没有这个问题：每个位置都有真下一词，难度由数据本身提供。这也是它在超大规模解码器上难被替换的原因——实现、吞吐、与采样接口三者对齐，替代目标必须在别处把账补回来，例如更好的双向表征，或同样算力下更快的下游迁移。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>今日主流生成模型预训练仍以 NTP 为主，并不等于其他目标被证伪。编码器、检索器、重排器仍大量使用掩码或对比；指令微调与思维链则是在 NTP 接口上换数据，不是换目标。把「超越 NTP」写成必须换损失，会漏掉更常见的做法：数据、配比、合成改写，损失仍是下一 token。</p><p>工程上，非 NTP 目标往往更难与因果推理栈共用内核。双向注意力不能直接套 KV 缓存；替换检测的判别头在生成时无用，要另接解码器；混合去噪需要任务哨兵，数据管道与打包格式都变。若最终产品是自回归聊天，为预训练换一套目标，必须能在迁移阶段把双向或判别能力转化成生成质量，否则多出来的实现复杂度没有回报。</p><p><span class="marginnote">为什么重要：KV 缓存只有在「新 token 只依赖旧 token」时才能增量复用。双向注意力里每个新 token 都要回看全句，缓存没法边生成边补——把双向预训练模型搬进生成服务，成本结构会整个改变，不只是改个掩码的事。</span></p><p><span class="marginnote">不要把「下一 token 之外」理解成必须抛弃似然。跨度破坏的解码器端仍是 NTP；UL2 的因果模式就是 NTP。真正换掉的常常是编码器可见性与噪声半径，而不是 softmax 交叉熵本身。</span></p><p>对照实验还应避免把架构差异算进目标差异：BERT 是编码器，GPT 是解码器，T5 是编码器-解码器。Raffel 等人在同一 T5 骨架上扫过多种噪声，才有资格谈目标；拿 BERT 分数和 GPT 分数直接比，比的是整条系统。本篇只讨论目标协议，不把某一架构写成唯一正确的预训练方式。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NTP 以外的预训练目标，核心是换噪声与可见性：掩码、跨度破坏、前缀条件、替换检测、混合去噪。</li><li>损失密度、条件方向、与下游接口是否同构，三者通常不能同时最优。</li><li>T5 把任务统一成文本到文本，跨度破坏是其中在生成设定下较划算的一种噪声，而不是对 NTP 的否定。</li><li>替换检测加密监督，但把生成改成判别，和自回归解码不对齐。</li><li>大规模解码器仍常回到 NTP，是因为实现、吞吐与采样接口一致；其他目标更多留在编码器与混合去噪里。</li><li>换目标不等于换似然：许多「非 NTP」协议在解码器端仍用下一 token 交叉熵。</li><li>出处：Raffel et al.，<em>Exploring the Limits of Transfer Learning with a Unified Text-to-Text Transformer</em>，JMLR 2020；对照 BERT 式掩码、前缀 LM 与后续混合去噪工作。</li></ul>',12))])}const F=A(p,[["render",T]]);export{_ as __pageData,F as default};
